/// Presenca de um usuario no mapa em tempo real (issue #50).
///
/// Armazena onde o usuario esta agora para que outros motoristas vejam
/// movimento na regiao (estilo Waze). A presenca expira por TTL para nao
/// deixar fantasma quando o app e fechado.
library;\n\nimport 'package:achar_vagas_app/geo/geohash.dart';\nimport 'package:cloud_firestore/cloud_firestore.dart';\nimport 'package:latlong2/latlong.dart';\n\n/// Precisao do geohash de consulta para presenca (~1-2 km, suficiente para\n/// agrupar usuarios na mesma regiao sem expor a posicao exata).\nconst int precisaoGeohashPresenca = 5;\n\n/// Registro de presenca de um usuario.\nclass Presenca {\n  const Presenca({\n    required this.uid,\n    required this.ponto,\n    required this.geohashConsulta,\n    required this.atualizadoEm,\n    this.id,\n  });\n\n  /// Monta a presenca a partir da posicao atual.\n  factory Presenca.novo({\n    required String uid,\n    required LatLng ponto,\n    DateTime? atualizadoEm,\n  }) =>\n      Presenca(\n        uid: uid,\n        ponto: ponto,\n        geohashConsulta: geohashCodificar(\n          ponto.latitude,\n          ponto.longitude,\n          precisao: precisaoGeohashPresenca,\n        ),\n        atualizadoEm: atualizadoEm ?? DateTime.now().toUtc(),\n      );\n\n  final String? id;\n  final String uid;\n  final LatLng ponto;\n  final String geohashConsulta;\n  final DateTime atualizadoEm;\n\n  /// `true` enquanto a presenca ainda e recente (dentro do TTL).\n  bool validaEm(DateTime agora, Duration ttl) =>\n      agora.difference(atualizadoEm) <= ttl;\n\n  Map<String, dynamic> toMap() => <String, dynamic>{\n        'uid': uid,\n        'geo': <String, dynamic>{\n          'geopoint': GeoPoint(ponto.latitude, ponto.longitude),\n          'geohashConsulta': geohashConsulta,\n        },\n        // Resolvido no servidor: as regras exigem atualizadoEm == request.time.\n        'atualizadoEm': FieldValue.serverTimestamp(),\n      };\n\n  static Presenca fromMap(String id, Map<String, dynamic> map) {\n    final geo = map['geo'] as Map<String, dynamic>;\n    final ponto = geo['geopoint'] as GeoPoint;\n    final atualizadoEm = map['atualizadoEm'];\n\n    return Presenca(\n      id: id,\n      uid: map['uid'] as String,\n      ponto: LatLng(ponto.latitude, ponto.longitude),\n      geohashConsulta: geo['geohashConsulta'] as String,\n      atualizadoEm: atualizadoEm is Timestamp\n          ? atualizadoEm.toDate()\n          : DateTime.now().toUtc(),\n    );\n  }\n\n  @override\n  String toString() => 'Presenca($uid em $ponto as $atualizadoEm)';\n}